var esc=function(s){ return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'); };
var keys=Object.keys(P); var map={};
keys.forEach(function(k){ map[k]=P[k]; var a=k.charAt(0), up=a.toUpperCase(), lo=a.toLowerCase();
  var r=P[k]; var rU=r.charAt(0).toUpperCase()+r.slice(1), rL=r.charAt(0).toLowerCase()+r.slice(1);
  if(a!==up&&!(up+k.slice(1) in P)) map[up+k.slice(1)]=rU; if(a!==lo&&!(lo+k.slice(1) in P)) map[lo+k.slice(1)]=rL; });
var all=Object.keys(map).sort(function(a,b){ return b.length-a.length; });
var L="A-Za-zА-Яа-яЁёʻʼ'’";
var RX=new RegExp("(^|[^"+L+"])("+all.map(esc).join('|')+")(?=$|[^"+L+"])",'g');
function plural(n,a,b,c){ n=Math.abs(n)%100; var d=n%10; if(n>10&&n<20) return c; if(d>1&&d<5) return b; if(d===1) return a; return c; }
